mapper.select:
SELECT

FROM EVENT_PARTICIPANT P
WHERE P.SEQ = #{seq}

SELECT

FROM EVENT_PARTICIPANT P
WHERE P.CHECK_CODE = #{checkCode}

SELECT

FROM EVENT_PARTICIPANT P
WHERE P.SURVEY_USER_SEQ = #{surveyUserSeq}

SELECT

FROM EVENT_PARTICIPANT P
INNER JOIN SURVEY_USER U ON P.SURVEY_USER_SEQ = U.SEQ
WHERE P.EVENT_SEQ = #{eventSeq}
AND U.DEL_YN = 'N'

    AND (
        U.USER_NAME LIKE CONCAT('%', #{keyword}, '%')
        OR P.DEPARTMENT LIKE CONCAT('%', #{keyword}, '%')
        OR P.POSITION LIKE CONCAT('%', #{keyword}, '%')
    )


    AND P.PARTICIPANT_TYPE = #{participantType}

ORDER BY P.REG_DATE DESC

    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM EVENT_PARTICIPANT P INNER JOIN SURVEY_USER U ON P.SURVEY_USER_SEQ = U.SEQ WHERE P.EVENT_SEQ = #{eventSeq} AND U.DEL_YN = 'N'
AND ( U.USER_NAME LIKE CONCAT('%', #{keyword}, '%') OR P.DEPARTMENT LIKE CONCAT('%', #{keyword}, '%') OR P.POSITION LIKE CONCAT('%', #{keyword}, '%') )
AND P.PARTICIPANT_TYPE = #{participantType}

SELECT EXISTS(
    SELECT 1 FROM EVENT_PARTICIPANT WHERE CHECK_CODE = #{checkCode}
)

SELECT EXISTS(
    SELECT 1
    FROM EVENT_PARTICIPANT P
    INNER JOIN SURVEY_USER U ON P.SURVEY_USER_SEQ = U.SEQ
    WHERE P.EVENT_SEQ = #{eventSeq}
    AND U.USER_NAME = #{userName}
    AND U.USER_PHONE = #{encryptedPhone}
    AND U.DEL_YN = 'N'
)
